import {closureAnalysis,acceptClosure} from './closures.js?v=53ebd752d1db3b5a';
import {uid} from './ids.js?v=53ebd752d1db3b5a';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export class ClosureUI{
 constructor(api){this.api=api;this.preview=null;$('#close-loop-btn').onclick=()=>this.open();}
 markup(state,unit=1,visible=()=>true){const records=[...state.tolerated.map(r=>({...r,valid:true})),...state.invalidClosures.map(r=>({...r,valid:false}))];if(this.preview)records.push({...this.preview,valid:true,preview:true});return `<g class="closure-markers" pointer-events="none">${records.filter(r=>r.a&&r.b&&(visible(r.a.pieceId)||visible(r.b.pieceId))).map(r=>{const {a,b}=r,color=r.valid?'#c27b2e':'#b44c48',text=r.preview?'待确认容差':r.valid?`容差闭合 · ${r.gap.toFixed(2)} mm / ${r.angle.toFixed(2)}°`:'闭合失效 · '+r.reason;return `<g><title>${esc(text)}</title><path d="M${a.x} ${a.y}L${b.x} ${b.y}" stroke="${color}" stroke-width="${2*unit}" stroke-dasharray="${3*unit} ${2*unit}"/><circle cx="${(a.x+b.x)/2}" cy="${(a.y+b.y)/2}" r="${6*unit}" fill="white" fill-opacity=".7" stroke="${color}" stroke-width="${1.5*unit}"/><text x="${(a.x+b.x)/2+10*unit}" y="${(a.y+b.y)/2-8*unit}" font-size="${10*unit}" fill="${color}">${esc(text)}</text></g>`;}).join('')}</g>`;}
 open(){const api=this.api,p=api.project(),parts=api.byId(),state=closureAnalysis(p,parts,{candidates:true,selected:api.selected()}),list=state.candidates;let chosen=list.findIndex(c=>c.eligible);if(chosen<0&&list.length)chosen=0;
 const name=e=>{const piece=p.pieces.find(p=>p.id===e?.pieceId),part=piece&&parts[piece.partId];return part?`${part.brand} ${part.sku} · 端点 ${e.index+1}`:'已删除的轨道';};
 api.modal('容差闭合 · 接受小误差',`<p>适用于整条线路最后闭环时的微小间隙。接受后计为容差连接，<b>不会拉伸轨道或改动厂家尺寸</b>；图纸和 3D 中保留橙色标记。</p><p class="shape-note">容差是本工具的设计估算，非厂家接头公差；实物能否闭合仍需试铺。高度、轨距和接口兼容要求保持不变。</p><details class="closure-rules"><summary>查看估算规则</summary><p>按两端间已连接线路的最短实体路径计算：间隙上限为长度的 0.15%，最小 0.6 mm、最大 8 mm；角度上限为 0.6° 加每米 0.3°，最高 3°。端点高度差须小于 0.5 mm。没有已连通路径的两组轨道不能直接容差闭环。</p></details>${api.selected().length?'<p class="shape-note">只查找涉及当前所选轨道的闭合点；取消选择后可检查整个沙盘。</p>':''}<h3>待闭合端点</h3>${list.length?`<label class="field">选择闭合位置<select id="closure-choice">${list.map((r,i)=>`<option value="${i}" ${i===chosen?'selected':''}>${esc(name(r.a))} ↔ ${esc(name(r.b))} · ${r.gap.toFixed(2)} mm${r.eligible?'':' · 超限'}</option>`).join('')}</select></label><div id="closure-preview" role="status"></div><button id="closure-accept" class="full-btn primary">接受此偏差并闭合</button>`:'<p class="shape-note">未找到可评估的近邻端点。候选须处于同一条已接通线路、相距不超过 8 mm、方向误差不超过 3°，且接口和高度兼容。已记录的闭合点可在下方管理。</p>'}${state.truncated?'<p class="warnings">候选较多，本次只检查部分位置；选中待闭合处附近的轨道可缩小范围。</p>':''}<h3>已记录的容差闭合</h3><div class="closure-records">${[...state.tolerated,...state.invalidClosures].map(r=>`<div class="closure-record"><div><strong>${r.eligible?'已接受容差':'已失效 · 不计作连接'}</strong><small>${esc(name(r.record.a))} ↔ ${esc(name(r.record.b))}</small><small>${r.eligible?`${r.gap.toFixed(2)} mm · ${r.angle.toFixed(2)}° · 路线 ${(r.length/1000).toFixed(2)} m`:esc(r.reason)}</small></div><button data-remove-closure="${esc(r.record.id)}">移除</button></div>`).join('')||'<p class="shape-note">暂无记录</p>'}</div>`);
 const update=()=>{const r=list[Number($('#closure-choice').value)];chosen=Number($('#closure-choice').value);this.preview=r;const a=r.a,b=r.b,legs=[a,b].map(e=>({x:e.x-Math.cos(e.angle*Math.PI/180)*30,y:e.y-Math.sin(e.angle*Math.PI/180)*30})),all=[a,b,...legs],minX=Math.min(...all.map(p=>p.x))-10,minY=Math.min(...all.map(p=>p.y))-10,w=Math.max(...all.map(p=>p.x))-minX+10,h=Math.max(...all.map(p=>p.y))-minY+10;
 $('#closure-preview').innerHTML=`<svg class="closure-preview" viewBox="${minX} ${minY} ${w} ${h}" role="img" aria-label="两个轨道端点的方向与间隙">${[a,b].map((e,i)=>`<path d="M${legs[i].x} ${legs[i].y}L${e.x} ${e.y}" stroke="#56755d" stroke-width="2"/><circle cx="${e.x}" cy="${e.y}" r="1.8" fill="#cf913d"/>`).join('')}<path d="M${a.x} ${a.y}L${b.x} ${b.y}" stroke="#c27b2e" stroke-width=".8" stroke-dasharray="1 1"/></svg><div class="closure-metrics"><span>端点间隙<b>${r.gap.toFixed(2)} mm</b><small>此路线允许 ≤ ${r.limits.gap.toFixed(2)} mm</small></span><span>方向误差<b>${r.angle.toFixed(2)}°</b><small>此路线允许 ≤ ${r.limits.angle.toFixed(2)}°</small></span><span>已连接路线<b>${(r.length/1000).toFixed(2)} m</b><small>两端高度差 ${r.height.toFixed(2)} mm</small></span></div>${r.eligible?'<p class="shape-note">处于软件估算范围内，接受后仍需实物试铺复核。</p>':`<p class="warnings">${esc(r.reason)}，请调整布局或更换轨道。</p>`}`;$('#closure-accept').disabled=!r.eligible;api.redraw();};
 if(list.length){$('#closure-choice').onchange=update;$('#closure-accept').onclick=()=>{const r=list[chosen];try{const checked=structuredClone(api.project());acceptClosure(checked,parts,r.a,r.b,uid());api.commit(p=>p.closures=checked.closures);$('#modal').close();api.toast('已按容差闭合，原始尺寸保留；橙色标记需实物复核');}catch(e){api.toast(e.message);}};update();}
 document.querySelectorAll('[data-remove-closure]').forEach(b=>b.onclick=()=>{this.preview=null;api.commit(p=>p.closures=p.closures.filter(r=>r.id!==b.dataset.removeClosure));this.open();});
 $('#modal').addEventListener('close',()=>{this.preview=null;api.redraw();},{once:true});
 }
}
